 const dialog=document.createElement('dialog');dialog.id='rcPriceFilterDialog';dialog.setAttribute('aria-labelledby','rcPriceFilterTitle');dialog.innerHTML=`<div class="rc-price-heading"><h2 id="rcPriceFilterTitle">${icon} Rentang Harga</h2><button type="button" data-price-close aria-label="Tutup rentang harga">×</button></div><p>Harga sewa per hari dalam Rupiah. Pilih rentang sesuai anggaran Anda.</p><form><div class="rc-price-fields"><label>Harga minimum (Rp)<input name="min" type="text" inputmode="numeric" autocomplete="off" placeholder="0"></label><label>Harga maksimum (Rp)<input name="max" type="text" inputmode="numeric" autocomplete="off" placeholder="Tanpa batas"></label></div><div class="rc-price-presets"><button type="button" data-price-preset="0,250000">≤ Rp250.000</button><button type="button" data-price-preset="250000,1000000">Rp250.000 – Rp1.000.000</button><button type="button" data-price-preset="1000000,">≥ Rp1.000.000</button></div><p data-price-error role="alert" hidden></p><div class="rc-price-actions"><button type="button" data-price-reset>Reset</button><button type="submit">Lihat produk</button></div></form>`;document.body.append(dialog);const form=dialog.querySelector('form');
