 form.addEventListener('input',e=>{const input=e.target;if(!['min','max'].includes(input.name))return;const before=input.value.slice(0,input.selectionStart).replace(/[^0-9]/g,'').length;input.value=formatted(input.value);let seen=0,caret=0;for(;caret<input.value.length&&seen<before;caret++)if(/[0-9]/.test(input.value[caret]))seen++;input.setSelectionRange(caret,caret)});
 function setRange(min,max,categories=null){const u=new URLSearchParams(location.search);for(const [k,v] of [['minPrice',min],['maxPrice',max]])if(v===null||v==='')u.delete(k);else u.set(k,String(v));if(categories!==null){u.delete('cat');if(categories.length)u.set('cats',categories.join(','));else u.delete('cats');}history.replaceState({},'',location.pathname+(u.size?'?'+u:''));if(window.RentcamCatalogPaging&&typeof window.rentcamSearch==='function')window.rentcamSearch();apply()}
 dialog.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-price-close'))dialog.close();if(b.hasAttribute('data-price-reset')){setRange(null,null,[]);if(typeof render==='function')render();dialog.close()}if(b.dataset.pricePreset){const [min,max]=b.dataset.pricePreset.split(',');form.elements.min.value=formatted(min);form.elements.max.value=formatted(max)}});
